import{_ as d,o as e,c as a,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"配置网络与防火墙","description":"分清中心管理入口、运行环境入口和可选独立入口，按实际地址与端口设置防火墙和云安全组。","frontmatter":{"title":"配置网络与防火墙","description":"分清中心管理入口、运行环境入口和可选独立入口，按实际地址与端口设置防火墙和云安全组。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/network.md","filePath":"zh/安装运维/配置网络与防火墙.md"}'),o={name:"zh/installation/network.md"};function n(l,t,i,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="配置网络与防火墙" tabindex="-1">配置网络与防火墙 <a class="header-anchor" href="#配置网络与防火墙" aria-label="Permalink to &quot;配置网络与防火墙&quot;">​</a></h1><p>先记住一条：<strong>在哪台服务器上提供访问，就在那台服务器上允许对应端口；只开放实际使用的入口。</strong> 不需要为了运行一个工程，把所有端口都打开。</p><p><strong>端口以你实际配置的值为准。</strong> 中心管理端口可以在安装时自定义，<code>18100</code> 只是默认值；环境入口和独立入口也分别使用各自设置的端口。手册中的默认值和例子不是必须开放的固定号码。</p><p>日常使用者只需向管理员取得访问地址；下面的设置由服务器维护人员完成。平台目前优先推荐已测试的 <strong>Ubuntu 24</strong>，其他系统尚未测试。防火墙与云安全组的具体组合仍需按现场实际访问核对。</p><h2 id="_1-先看自己要打开哪一种入口" tabindex="-1">1. 先看自己要打开哪一种入口 <a class="header-anchor" href="#_1-先看自己要打开哪一种入口" aria-label="Permalink to &quot;1. 先看自己要打开哪一种入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你要做什么</th><th>应使用哪个入口</th><th>要开放哪里</th></tr></thead><tbody><tr><td>管理平台、组织等中心设置</td><td>中心管理入口</td><td>中心实际配置的管理端口（默认 <code>18100</code>），只允许管理员所在的可信网络访问</td></tr><tr><td>登录平台，开发应用或查看数据中心</td><td>安装时给出的平台公共入口，当前默认 HTTPS <code>443</code></td><td>中心服务器实际配置的公共端口，允许需要使用平台的人访问</td></tr><tr><td>打开已经运行的工程应用</td><td>运行环境的“访问入口”</td><td>该入口所在节点上设置的环境端口</td></tr><tr><td>不经过环境入口，独立打开某个工程</td><td>工程部署中的“节点直连”</td><td>该工程部署所在节点上设置的独立端口；未启用时不需要开放</td></tr></tbody></table><p><strong>中心管理端口不是工程运行端口。</strong> 只开放 <code>18100</code>，不能代替开放环境入口；工程页面也不应拿中心的 <code>/admin/</code> 地址来打开。</p><p>“公共入口”不表示一定向所有互联网用户开放。仅公司内部使用时，可以只允许公司网络或 VPN 访问。管理入口使用 HTTP，默认只在内网提供，不要直接映射到公网。</p><h2 id="_2-去哪里查实际端口" tabindex="-1">2. 去哪里查实际端口 <a class="header-anchor" href="#_2-去哪里查实际端口" aria-label="Permalink to &quot;2. 去哪里查实际端口&quot;">​</a></h2><p>不要凭记忆填写，也不要照抄别人的端口：</p><ol><li><strong>中心管理入口</strong>：查看安装完成时给出的完整管理地址，使用其中实际的端口，路径带 <code>/admin/</code>。例如安装时把管理端口改成了 <code>18180</code>，就开放 <code>18180</code>，不是再开放默认的 <code>18100</code>。</li><li><strong>平台日常登录入口</strong>：查看安装结果中的公共地址；端口改过时，以安装结果为准。</li><li><strong>环境入口</strong>：进入 <strong>“运维管理” → “运行概览”</strong>，选中环境，打开 <strong>“访问入口”</strong>，记录运行节点、入口地址和端口。详见<a href="/induframe-docs/zh/guide/environment-entry.html">配置运行环境访问入口</a>。</li><li><strong>独立入口</strong>：打开对应工程部署，确认是否启用了 <strong>“节点直连”</strong>，记录部署节点和独立访问地址。详见<a href="/induframe-docs/zh/guide/deployments.html">创建和管理工程部署</a>。</li></ol><p>环境入口和独立入口可以同时启用。如果只通过环境入口访问，就不必再给这个工程单独开放一个端口；如果两者都要用，就分别允许两个实际入口。</p><div class="tip custom-block"><p class="custom-block-title">用一个例子理解</p><p>假设中心管理端口是 <code>18100</code>，某环境在 A 节点上的入口端口是 <code>17800</code>：</p><ul><li>管理员访问中心：允许管理员连接<strong>中心服务器的 <code>18100</code></strong>。</li><li>使用者打开这个环境里的工程：允许他们连接 <strong>A 节点的 <code>17800</code></strong>，不必每个工程另开端口。</li><li>某工程另外启用了 B 节点的独立端口 <code>17810</code>：只有需要独立访问时，才再允许他们连接 <strong>B 节点的 <code>17810</code></strong>。</li></ul><p><code>17800</code>、<code>17810</code> 都只是例子，不是默认值。地址以页面提供的完整链接为准，不手工丢掉工程路径。</p></div><h2 id="_3-整理一张开放申请表" tabindex="-1">3. 整理一张开放申请表 <a class="header-anchor" href="#_3-整理一张开放申请表" aria-label="Permalink to &quot;3. 整理一张开放申请表&quot;">​</a></h2><p>把下面几项发给维护人员，就不容易出现“端口开了，但开错机器”的情况：</p><table tabindex="0"><thead><tr><th>要写清什么</th><th>填写方法</th></tr></thead><tbody><tr><td>谁需要访问</td><td>管理员电脑、公司办公网络、VPN 使用者或指定业务使用者</td></tr><tr><td>访问哪台服务器</td><td>中心服务器，或页面中显示的入口所在节点；不能只写“平台”</td></tr><tr><td>开放哪个端口</td><td>填实际使用的单个端口，例如管理入口默认 <code>18100</code></td></tr><tr><td>通信方式</td><td>本页这些网页入口选择 <code>TCP</code>；后台节点通信另外按参考清单处理</td></tr><tr><td>用途</td><td>中心管理、平台日常操作、环境入口或独立访问</td></tr></tbody></table><p>如果不知道访问者的来源地址，请维护人员确认。经过 VPN、跳板机或其他网络设备后，服务器看到的来源可能与电脑显示的地址不同；不要为了省事直接允许所有来源。</p><h2 id="_4-设置服务器防火墙和云安全组" tabindex="-1">4. 设置服务器防火墙和云安全组 <a class="header-anchor" href="#_4-设置服务器防火墙和云安全组" aria-label="Permalink to &quot;4. 设置服务器防火墙和云安全组&quot;">​</a></h2><h3 id="服务器本身的防火墙" tabindex="-1">服务器本身的防火墙 <a class="header-anchor" href="#服务器本身的防火墙" aria-label="Permalink to &quot;服务器本身的防火墙&quot;">​</a></h3><p>先允许自己正在使用的远程管理连接，再增加上述入口规则。修改前保留当前 SSH 会话，并确认可以从云控制台或现场控制台恢复。</p><p>Ubuntu 24 的 UFW 命令示例单独放在<a href="/induframe-docs/zh/reference/network-ports.html#ubuntu-24-的-ufw-入口示例">网络与端口清单</a>，由维护人员按自己的地址修改后执行。不熟悉服务器管理时，不需要自己尝试这些命令。</p><p><strong>已有的宽泛允许规则不会被新白名单自动收紧。</strong> 如果以前已经允许所有人访问某端口，要先确认用途，再删除不需要的旧规则，而不是只增加一条限制来源的规则就认为完成了。</p><h3 id="云服务器的安全组" tabindex="-1">云服务器的安全组 <a class="header-anchor" href="#云服务器的安全组" aria-label="Permalink to &quot;云服务器的安全组&quot;">​</a></h3><p>若服务器放在云平台，还要到云服务器控制台，检查这台服务器实际绑定的安全组：</p><ol><li>找到接收入站连接的规则。</li><li>选择正确协议，填写实际端口。</li><li>来源填写指定使用者的网络或地址；中心管理入口只允许管理员来源。</li><li>保存后实际访问，不能只看控制台显示“保存成功”。</li></ol><p>主机防火墙和云安全组是两层设置，只改一层可能仍打不开。若还有机房防火墙或 VPN，也需要维护人员一起确认。</p><div class="warning custom-block"><p class="custom-block-title">不要只依靠一条 UFW 规则判断安全</p><p>平台的一些入口由容器转发提供，可能不经过普通主机入站规则。只写一条 UFW 来源限制，不能保证其他来源就一定无法访问。</p><p>管理入口等敏感连接应配合云安全组或上游网络防火墙限制来源，并从允许和不允许的两侧实测。不要关闭整个防火墙、清空网络规则或开放全部端口来“修复”。</p></div><h2 id="_5-多台节点还要确认后台连接" tabindex="-1">5. 多台节点还要确认后台连接 <a class="header-anchor" href="#_5-多台节点还要确认后台连接" aria-label="Permalink to &quot;5. 多台节点还要确认后台连接&quot;">​</a></h2><p><strong>这一步解决的是“服务器之间能不能一起工作”，不是“用户能不能打开网页”。</strong> 中心和接入的节点合起来称为集群；它们还需要在后台互相连接，才能完成接入、下载运行程序和跨机器运行。</p><p>如果目前只有一台中心、没有另外接入节点，暂时不需要增加其他机器的互通规则，但仍要保留中心自己的内部网络。准备增加节点时，再按下面处理。</p><h3 id="先把机器认清楚" tabindex="-1">先把机器认清楚 <a class="header-anchor" href="#先把机器认清楚" aria-label="Permalink to &quot;先把机器认清楚&quot;">​</a></h3><p>假设准备使用一台中心、两台节点。先把下面的示例地址替换成自己的实际内网地址：</p><table tabindex="0"><thead><tr><th>机器</th><th>它负责什么</th><th>示例内网地址</th></tr></thead><tbody><tr><td>中心</td><td>安装了平台中心的服务器</td><td><code>10.20.0.10</code></td></tr><tr><td>节点 A</td><td>准备接入的第一台服务器</td><td><code>10.20.0.11</code></td></tr><tr><td>节点 B</td><td>准备接入的第二台服务器</td><td><code>10.20.0.12</code></td></tr></tbody></table><p>未接入时向服务器负责人取得地址；已接入时，可以对照 <strong>“运维管理” → “节点管理”</strong> 中的实际地址核对。这里填的是<strong>服务器的内网地址，不是管理员电脑的地址，也不是工程页面链接</strong>。</p><p>两台节点都需要连接中心，节点之间也要按需要互通：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中心 ↔ 节点 A</span></span>
<span class="line"><span>中心 ↔ 节点 B</span></span>
<span class="line"><span>节点 A ↔ 节点 B</span></span></code></pre></div><p>箭头表示按<a href="/induframe-docs/zh/reference/network-ports.html#中心与接入节点的后台通信">后台通信清单</a>允许相应连接，不是把双方所有端口全部开放。只有一个接入节点时，先处理中心与这台节点之间的连接即可。</p><h3 id="第一步-在中心允许这些节点连接" tabindex="-1">第一步：在中心允许这些节点连接 <a class="header-anchor" href="#第一步-在中心允许这些节点连接" aria-label="Permalink to &quot;第一步：在中心允许这些节点连接&quot;">​</a></h3><p>在<strong>中心服务器的防火墙及对应云安全组</strong>中，把节点 A、节点 B 的实际内网地址加入所需规则的允许来源；不要填管理员电脑的地址，也不要允许所有来源。</p><p>中心需要让节点完成四件事：</p><ul><li><strong>联系平台</strong>：使用节点安装包或页面给出的中心地址。不要拿中心管理登录地址代替；公共端口改过时，使用改后的值。</li><li><strong>加入集群</strong>：允许节点连接中心的 <code>6443/TCP</code>，使它成为一起工作的服务器。</li><li><strong>下载运行程序</strong>：允许节点访问中心下发的镜像仓库地址和实际端口，默认仓库端口为 <code>5000/TCP</code>。</li><li><strong>校准时间</strong>：允许节点访问指定校时服务，使用 <code>123/UDP</code>。如果校时服务不在中心，就在实际提供校时的机器上检查规则。</li></ul><p>中心同时也要参加下面的节点间通信。维护人员可按<a href="/induframe-docs/zh/reference/network-ports.html#第一步-在中心服务器设置">中心服务器设置表</a>逐项填写，不能只开放一个管理端口就认为完成。</p><h3 id="第二步-在每台节点允许中心和其他节点连接" tabindex="-1">第二步：在每台节点允许中心和其他节点连接 <a class="header-anchor" href="#第二步-在每台节点允许中心和其他节点连接" aria-label="Permalink to &quot;第二步：在每台节点允许中心和其他节点连接&quot;">​</a></h3><p><strong>这一步要在每台节点分别设置，不是只改中心。</strong></p><ul><li>在节点 A 上，允许来源为中心和节点 B 的对应后台连接。</li><li>在节点 B 上，允许来源为中心和节点 A 的对应后台连接。</li><li>在中心上，允许来源为节点 A 和节点 B 的对应后台连接。</li></ul><p>这些节点间连接包括运行程序跨机器通信所需的 <code>8472/UDP</code>，以及读取节点状态指标所需的 <code>10250/TCP</code>。维护人员按<a href="/induframe-docs/zh/reference/network-ports.html#第二步-在每台节点设置">每台节点设置表</a>分别选择协议和端口；只允许这组可信服务器，不向公网开放。</p><p>如果服务器限制了向外连接，还要检查它能否主动连接对方。防火墙的“入站”是别人连进来，“出站”是自己连出去；只配置一边，另一边仍可能不通。</p><p>以后新增节点 C 时，除了配置 C，还要更新中心及原有节点的允许来源。不要只配置新机器，也不要为了方便把整片网络都设为可信来源。</p><details class="details custom-block"><summary>交给维护人员一起确认的内部网络</summary><p>当前平台内部还使用 <code>10.42.0.0/16</code>、<code>10.43.0.0/16</code> 两个地址范围。请维护人员在安装前确认它们与公司、VPN 和设备网络不冲突，并检查服务器内部的数据转发规则。</p><p>普通使用者不需要把电脑接入这些地址，也不要手工改它们。若机器分布在不同网络，先由网络管理员确认内网路由或受控 VPN 能连通，不通过把后台端口暴露到公网来绕过。</p></details><h3 id="第三步-接入后按结果确认-而不只看-在线" tabindex="-1">第三步：接入后按结果确认，而不只看“在线” <a class="header-anchor" href="#第三步-接入后按结果确认-而不只看-在线" aria-label="Permalink to &quot;第三步：接入后按结果确认，而不只看“在线”&quot;">​</a></h3><p>按照<a href="/induframe-docs/zh/guide/runtime-nodes.html">节点接入步骤</a>完成安装和确认，再逐台检查：</p><table tabindex="0"><thead><tr><th>检查什么</th><th>应看到什么</th><th>没达到时先查哪一段</th></tr></thead><tbody><tr><td>节点是否联系到中心</td><td>节点管理中能看到该服务器，连接与最近心跳有更新</td><td>节点使用的中心地址、实际公共端口和接入资料</td></tr><tr><td>是否已具备运行条件</td><td>安装过程及节点页面没有未处理的集群加入或运行资格提示；请维护人员确认</td><td>节点到中心 <code>6443/TCP</code> 的连接及实际加入结果</td></tr><tr><td>运行程序能否准备好</td><td>需要运行时，维护人员确认所需镜像可以正常下载</td><td>仓库实际地址、端口、证书和权限</td></tr><tr><td>时间是否正常</td><td>节点的时间同步信息没有未处理的异常</td><td>到指定校时服务的连接及服务允许来源</td></tr><tr><td>跨机器运行是否正常</td><td>在已有、获准的测试工程中核对实际跨节点使用结果</td><td>节点间连接和内部转发；不能只用网页或“在线”状态代替</td></tr></tbody></table><p>有异常时记录<strong>哪台机器连接哪台机器、要完成什么、看到什么提示</strong>，再交给维护人员排查。节点在线，只能说明它已经能与平台建立部分联系，不代表上面所有步骤都完成了。</p><h2 id="_6-怎样确认设置好了" tabindex="-1">6. 怎样确认设置好了 <a class="header-anchor" href="#_6-怎样确认设置好了" aria-label="Permalink to &quot;6. 怎样确认设置好了&quot;">​</a></h2><ul><li>从<strong>管理员实际使用的电脑或 VPN</strong>打开中心管理入口；重新建立一次 SSH 连接，确认没有把自己挡在服务器外。</li><li>从<strong>业务使用者的电脑</strong>打开环境入口中的工程，核对工程路径、登录和页面内容。</li><li>若启用了独立访问，再单独打开对应独立地址；只验证环境入口，不能代替验证独立入口。</li><li>请维护人员从<strong>不在白名单的受控测试电脑</strong>验证管理入口等敏感端口确实无法访问，而不是还能出现登录页。</li><li>多节点时，还要确认节点加入、镜像下载和跨节点运行结果，不只看一个“在线”状态。</li></ul><p>不能只在服务器自己打开页面，因为它与远程使用者经过的网络可能不同。HTTPS 提示证书不受信任或名称不匹配时，应检查证书和地址，不应当成端口没开而继续放宽规则。</p><h2 id="_7-打不开时按这个顺序检查" tabindex="-1">7. 打不开时按这个顺序检查 <a class="header-anchor" href="#_7-打不开时按这个顺序检查" aria-label="Permalink to &quot;7. 打不开时按这个顺序检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>先做什么</th></tr></thead><tbody><tr><td>地址一直超时</td><td>核对服务器、端口、访问来源、防火墙、安全组与路由，确认规则开在正确机器上</td></tr><tr><td>提示连接被拒绝</td><td>确认地址和端口正确、入口确实已启用并就绪；不要只反复添加规则</td></tr><tr><td>中心能打开，工程打不开</td><td>改用环境或独立入口的完整地址，检查对应节点，而不是继续开放中心端口</td></tr><tr><td>环境入口能打开，独立地址打不开</td><td>确认工程部署启用了“节点直连”，再检查部署节点和独立端口</td></tr><tr><td>证书警告</td><td>让维护人员核对证书、适用域名和有效期，不关闭浏览器安全验证</td></tr><tr><td>登录页能打开，但业务报无权限</td><td>连接已到达服务，继续检查工程账号和权限，不是再开放更多端口</td></tr><tr><td>节点在线，工程仍未正常运行</td><td>请维护人员检查后台连接和实际部署状态，见<a href="/induframe-docs/zh/guide/runtime-data-troubleshooting.html">运行问题排查</a></td></tr></tbody></table><h2 id="_8-改端口或卸载后也要整理规则" tabindex="-1">8. 改端口或卸载后也要整理规则 <a class="header-anchor" href="#_8-改端口或卸载后也要整理规则" aria-label="Permalink to &quot;8. 改端口或卸载后也要整理规则&quot;">​</a></h2><p>更改入口端口、删除节点或不再需要独立访问时，通知受影响的使用者，更新链接，并由维护人员移除确定不再使用的防火墙及安全组规则。</p><p>平台页面关闭入口、删除部署或卸载程序，不等于替你撤销所有自定义网络规则。删除前确认其他工程或服务没有继续使用，保留 SSH 和共享集群需要的连接。</p><p>下一步：<a href="/induframe-docs/zh/installation/install.html">安装中心</a> · <a href="/induframe-docs/zh/guide/environment-entry.html">配置环境入口</a> · <a href="/induframe-docs/zh/reference/network-ports.html">端口清单与维护示例</a>。</p>`,62)])])}const g=d(o,[["render",n]]);export{u as __pageData,g as default};
